# frozen_string_literal: true

RSpec.describe Lethe::Exporter do
  let(:root) { File.expand_path("../..", __dir__) }
  let(:models) { sns_schema }

  def exporter(locale: :en)
    models
    sns_definitions(complete: true)
    described_class.new(
      check(models), definitions: Lethe.definitions.values, models: models, root: root,
      definition_path: File.join(root, "config/lethe.rb"), locale: locale
    )
  end

  it "writes a Markdown table, the subject's own row first" do
    expect(exporter.markdown).to eq(<<~MARKDOWN)
      <!-- Generated by lethe from config/lethe.rb. Do not edit by hand; run bin/rails lethe:export. -->

      # What happens when a User leaves

      | Data | When they leave | Kept for | Reason |
      | --- | --- | --- | --- |
      | The User itself | Kept as deleted (deleted_at), with nickname, email overwritten |  |  |
      | Avatar (attachment) | Deleted |  |  |
      | Follow (follower_id) | Deleted |  |  |
      | Follow (following_id) | Deleted |  |  |
      | Inquiry | Kept | 2 years | Support history |
      | Muted user (muted_user_id) | Kept |  | Other people's settings |
      | Muted user | Deleted |  |  |
      | Post | Kept, with body overwritten |  | Quoted posts keep their row |
    MARKDOWN
  end

  it "writes Japanese" do
    expect(exporter(locale: :ja).markdown).to include(
      "# User が退会するとどうなるか",
      "| User 本体 | 削除済みとして残す（deleted_at）。nickname、email は書き換える |  |  |",
      "| Inquiry | 残す | 2 年 | Support history |"
    )
  end

  it "uses the application's translations for model names" do
    I18n.backend.store_translations(:ja, activerecord: {models: {inquiry: "問い合わせ"}})

    expect(exporter(locale: :ja).markdown).to include("| 問い合わせ | 残す | 2 年 | Support history |")
  ensure
    I18n.reload!
  end

  it "writes JSON for tools" do
    data = JSON.parse(exporter.json)

    expect(data["version"]).to eq(1)
    user = data["subjects"].sole
    expect(user["subject_row"]).to eq("destroy" => false, "soft_delete" => "deleted_at", "scrub" => %w[nickname email])
    expect(user["data"].find { |row| row["key"] == "inquiries.user_id" }).to eq(
      "key" => "inquiries.user_id", "table" => "inquiries", "column" => "user_id", "label" => "Inquiry",
      "action" => "keep", "retention_seconds" => 2.years.to_i, "retention" => "2 years", "reason" => "Support history"
    )
    expect(user["data"].find { |row| row["key"] == "attachment:avatar" }).to include("attachment" => "avatar", "action" => "destroy_attachment")
    expect(user["data"].find { |row| row["key"] == "posts.user_id" }).to include("set" => ["body"])
  end

  it "shows conditions, and leaves ignored references out" do
    models
    Lethe.define("User") do
      subject destroy: true
      scrub :posts, where: {body: %w[a b]}, set: {body: "x|y"}, reason: "two\nlines"
      destroy "follows.follower_id", "follows.following_id", :muted_users, :inquiries
      ignore "muted_users.muted_user_id", reason: "not a user"
      destroy_attachments :avatar
    end
    markdown = described_class.new(
      check(models), definitions: Lethe.definitions.values, models: models, root: root,
      definition_path: File.join(root, "config/lethe.rb")
    ).markdown

    expect(markdown).to include(
      "| The User itself | Deleted |  |  |",
      "| Post | Kept, with body overwritten, where body = a / b |  | two lines |"
    )
    expect(markdown).not_to include("muted_user_id")
  end
end
